macro.command:
// RealityCollapse DAE macro — DEBUG version
// 放在 DAE Active Effect 的 Macro 字段（效果创建/删除时都会触发）
// 目的：创建时注册 hook，在回合开始触发 d10 表；删除时注销 hook。
// 该版本包含大量 console.log/ChatMessage 以便排查为何没有触发。

(async () => {
  try {
    const lastArg = args?.[0] ?? args?.[args.length-1] ?? {};
    console.groupCollapsed("RealityCollapse DEBUG: invoked macro");
    console.log("args[0] snapshot:", lastArg);
    console.log("full args:", args);
    console.groupEnd();

    // 解析 tag/操作类型（尝试多种策略）
    const tagRaw = String(lastArg.tag ?? "").toLowerCase();
    const verbFromTag = (tagRaw.includes("on") || tagRaw.includes("apply") || tagRaw.includes("create")) ? "apply" :
                        (tagRaw.includes("off") || tagRaw.includes("remove") || tagRaw.includes("delete")) ? "remove" : null;
    const isApply = verbFromTag === "apply" || (verbFromTag === null && !!lastArg?.ef && !lastArg?.expired);
    const isRemove = verbFromTag === "remove" || (verbFromTag === null && !!lastArg?.ef && !!lastArg?.expired);

    console.log("RealityCollapse DEBUG: tagRaw=", tagRaw, "verbFromTag=", verbFromTag, "=> isApply=", isApply, "isRemove=", isRemove);

    const effect = lastArg.ef ?? lastArg.effect ?? undefined;
    console.log("RealityCollapse DEBUG: resolved effect:", effect);

    // 尝试多种方式解析 tokenId / actorId
    const tokenIdCandidates = [
      lastArg.tokenId ?? null,
      lastArg.token?.id ?? null,
      lastArg.token?.uuid ?? null,
      lastArg.tokenUuid ?? null,
      effect?.parent?.id ?? null,
      effect?.parent?._id ?? null
    ].filter(Boolean);
    const tokenId = tokenIdCandidates[0] ?? undefined;

    const actorIdCandidates = [
      lastArg.actorId ?? lastArg.actorUuid ?? lastArg.actor?._id ?? null,
      effect?.parent?.id ?? effect?.parent?._id ?? null
    ].filter(Boolean);
    const actorId = actorIdCandidates[0] ?? undefined;

    console.log("RealityCollapse DEBUG: tokenIdCandidates=", tokenIdCandidates, "=> chosen tokenId=", tokenId);
    console.log("RealityCollapse DEBUG: actorIdCandidates=", actorIdCandidates, "=> chosen actorId=", actorId);

    // Ensure global registry exists
    if (!window._realityCollapseHooks) {
      window._realityCollapseHooks = {};
      console.log("RealityCollapse DEBUG: created window._realityCollapseHooks");
    }

    // Key 用 effect.id 或 actorId 做唯一标识
    const efKey = effect?.id ? `ef.${effect.id}` : (effect?.uuid ? `efuuid.${effect.uuid}` : `actor.${actorId}`);
    console.log("RealityCollapse DEBUG: efKey=", efKey);

    // 辅助：复制 item AE（用于 stun/prone/blind）
    async function copyItemAEFromOriginToTarget(originUuid, targetActor, keywords = []) {
      console.log("RealityCollapse DEBUG: copyItemAEFromOriginToTarget called", { originUuid, targetActorName: targetActor?.name, keywords });
      if (!originUuid) { console.warn("RealityCollapse DEBUG: no originUuid"); return false; }
      try {
        const itemDoc = await fromUuid(originUuid).catch(e => { console.warn("RealityCollapse DEBUG: fromUuid origin failed", e); return null; });
        if (!itemDoc) { console.log("RealityCollapse DEBUG: origin not resolvable to Item"); return false; }
        if (itemDoc.documentName !== "Item") { console.log("RealityCollapse DEBUG: origin resolved but not an Item:", itemDoc.documentName); return false; }
        const item = itemDoc;
        console.log("RealityCollapse DEBUG: found origin item", item.name);
        const lower = s => String(s ?? "").toLowerCase();
        const ef = item.effects.find(e => {
          const nm = lower(e.name ?? e.label ?? e.data?.name ?? "");
          return keywords.some(k => nm.includes(k));
        });
        if (!ef) { console.log("RealityCollapse DEBUG: no matching AE on origin item (keywords)", keywords); return false; }
        console.log("RealityCollapse DEBUG: found AE on item:", ef.name ?? ef.label ?? ef.data?.name);
        let data = ef.toObject ? ef.toObject() : duplicate(ef);
        if (data._id) delete data._id;
        data.origin = originUuid;
        // 使用 GM 执行更可靠，但这里尽量直接创建（如需 GM 则后面改为 socket）
        await targetActor.createEmbeddedDocuments("ActiveEffect", [data]);
        console.log("RealityCollapse DEBUG: successfully applied AE to target actor:", targetActor.name);
        return true;
      } catch (e) {
        console.error("RealityCollapse DEBUG: copyItemAEFromOriginToTarget error", e);
        return false;
      }
    }

    // 辅助：apply damage via MidiQOL
    async function applyDamageFormula(casterActor, casterToken, targetToken, formula, dtype, flavor) {
      console.log("RealityCollapse DEBUG: applyDamageFormula called", { casterActorName: casterActor?.name, targetTokenName: targetToken?.name, formula, dtype, flavor });
      try {
        const r = new Roll(formula);
        if (typeof r.evaluateSync === "function") r.evaluateSync(); else await r.roll();
        console.log("RealityCollapse DEBUG: roll result", r.formula, r.total);
        await new MidiQOL.DamageOnlyWorkflow(casterActor ?? targetToken.actor, casterToken ?? undefined, Number(r.total), dtype, [targetToken], r, {
          flavor: flavor ?? `${dtype}`,
          itemCardId: effect?.origin ?? null,
          itemData: {},
          useOther: false
        });
        console.log("RealityCollapse DEBUG: DamageOnlyWorkflow done for", targetToken.name);
        return Number(r.total);
      } catch (e) {
        console.error("RealityCollapse DEBUG: applyDamageFormula failed", e);
        ChatMessage.create({ content: `RealityCollapse: 无法自动应用 ${formula} ${dtype} 到 ${targetToken.name}（请 GM 手动处理）` });
        return null;
      }
    }

    // 构造 handler（on updateCombat 时调用）
    function makeHandler(forTokenId, forEfKey, originUuid) {
      const handler = async (combat, changed, options, userId) => {
        try {
          console.groupCollapsed(`RealityCollapse DEBUG: handler invoked forEfKey=${forEfKey}`);
          console.log("handler args changed:", changed, "combatant:", combat?.combatant);
          // Only proceed on turn change events
          if (!(changed?.turn !== undefined || changed?.round !== undefined)) {
            console.log("handler: changed does not include turn/round -> ignore");
            console.groupEnd();
            return;
          }
          const combatant = combat?.combatant;
          if (!combatant) { console.log("handler: no combatant -> ignore"); console.groupEnd(); return; }
          const activeTokenId = combatant.tokenId ?? combatant.token?.id;
          console.log("handler: activeTokenId=", activeTokenId, "forTokenId=", forTokenId);
          if (String(activeTokenId) !== String(forTokenId)) { console.log("handler: not target's turn -> ignore"); console.groupEnd(); return; }

          const targetToken = canvas.tokens.get(forTokenId);
          if (!targetToken) { console.warn("handler: target token missing on canvas"); console.groupEnd(); return; }
          const targetActor = targetToken.actor;
          console.log("handler: target is on turn => executing d10 table for", targetActor.name);

          // find caster if possible
          let casterActor, casterToken;
          if (originUuid) {
            try {
              const doc = await fromUuid(originUuid).catch(()=>null);
              if (doc?.documentName === "Item") {
                casterActor = doc.parent ?? undefined;
                casterToken = canvas.tokens.placeables.find(t => t.actor?.id === casterActor?.id);
              } else if (doc?.documentName === "Actor") {
                casterActor = doc;
                casterToken = canvas.tokens.placeables.find(t => t.actor?.id === casterActor?.id);
              }
            } catch (e) { console.warn("handler: origin->fromUuid failed", e); }
          }
          if (!casterActor) {
            casterToken = canvas.tokens.controlled[0];
            casterActor = casterToken?.actor;
            console.log("handler: fallback casterActor from controlled token:", casterActor?.name);
          } else console.log("handler: found casterActor", casterActor?.name);

          // roll d10
          const d10r = new Roll("1d10");
          if (typeof d10r.evaluateSync === "function") d10r.evaluateSync(); else await d10r.roll();
          const d10 = Number(d10r.total);
          ChatMessage.create({ content: `${targetActor.name} 的 RealityCollapse 判定：d10 = ${d10}` });
          console.log("handler: rolled d10 =", d10);

          // compute DC (try from effect flags)
          let dc = 15;
          try {
            if (effect?.flags?.["reality-collapse"]?.dc) dc = Number(effect.flags["reality-collapse"].dc);
            else if (effect?.flags?.dae?.dc) dc = Number(effect.flags.dae.dc);
            else if (effect?.changes?.length) {
              const c = effect.changes.find(ch => String(ch.key ?? "").toLowerCase().includes("save") || String(ch.key ?? "").toLowerCase().includes("dc"));
              if (c) dc = Number(c.value ?? dc);
            }
          } catch(e) { console.warn("handler: DC extraction failed", e); }
          console.log("handler: DC used =", dc);

          // Branch: 1-2
          if (d10 >= 1 && d10 <= 2) {
            console.log("handler: branch 1-2 -> 6d12 psychic + stun to end of round");
            await applyDamageFormula(casterActor, casterToken, targetToken, "6d12", "psychic", "Reality Collapse — 遥远国度之瞥 (psychic)");
            const ok = await copyItemAEFromOriginToTarget(originUuid, targetActor, ["stun","stunned","震慑"]);
            if (!ok) {
              // fallback AE
              const ae = {
                label: "Stunned (Reality Collapse)",
                icon: "icons/skills/wounds/injury-blood-loss-stunned.webp",
                origin: originUuid ?? null,
                disabled: false,
                duration: { rounds: 1, startRound: game.combat?.round ?? 0, startTurn: game.combat?.turn ?? 0 },
                changes: []
              };
              await targetActor.createEmbeddedDocuments("ActiveEffect", [ae]).catch(e=>console.warn("handler: create fallback stun AE failed", e));
              ChatMessage.create({ content: `${targetActor.name} 受到震慑直到本轮结束（fallback AE）` });
            } else ChatMessage.create({ content: `${targetActor.name} 被施加 震慑（来自施法物品 AE）` });
            console.groupEnd();
            return;
          }

          // Branch: 3-5 dex save vs dc -> 8d12 force (half on success)
          if (d10 >= 3 && d10 <= 5) {
            console.log("handler: branch 3-5 -> Dex save vs", dc);
            let save = undefined;
            if (typeof targetActor.rollSavingThrow === "function") save = await targetActor.rollSavingThrow("dex", { fastForward: false, chatMessage: true });
            else if (typeof targetActor.rollAbilitySave === "function") save = await targetActor.rollAbilitySave("dex", { fastForward: false, chatMessage: true });
            else {
              ChatMessage.create({ content: `${targetActor.name} 无法使用系统豁免 API，請 GM 手动处理 崩碎裂缝 (8d12 force)` });
              console.warn("handler: target lacks save API -> aborting branch 3-5");
              console.groupEnd();
              return;
            }
            const saveTotal = Number(save?.total ?? save?.results?.[0]?.result ?? 0);
            const success = saveTotal >= dc;
            console.log("handler: dex save result", saveTotal, "success=", success);
            // roll 8d12 and apply half/full
            const rr = new Roll("8d12"); if (typeof rr.evaluateSync === "function") rr.evaluateSync(); else await rr.roll();
            const raw = Number(rr.total);
            const toDeal = success ? Math.floor(raw/2) : raw;
            await new MidiQOL.DamageOnlyWorkflow(casterActor ?? targetActor, casterToken ?? undefined, toDeal, "force", [targetToken], rr, { flavor: "Reality Collapse — 崩碎裂缝 (force)" });
            ChatMessage.create({ content: `${targetActor.name} 的 Dex 豁免 ${saveTotal} vs DC ${dc} -> ${success ? "成功（半伤）" : "失败（全伤）"}，造成 ${toDeal} 力场伤害` });
            console.groupEnd();
            return;
          }

          // Branch: 6-8 teleport & 10d12 force + prone
          if (d10 >= 6 && d10 <= 8) {
            console.log("handler: branch 6-8 -> teleport within 30ft + 10d12 force + prone");
            // find a free snapped position within 30 ft
            const maxFeet = 30;
            const gridSize = canvas.grid.size;
            const feetPerSquare = canvas.scene.grid.distance;
            const pixelsPerFoot = gridSize / feetPerSquare;
            const maxPx = maxFeet * pixelsPerFoot;
            const originX = targetToken.x + (targetToken.w / 2);
            const originY = targetToken.y + (targetToken.h / 2);
            let dest = null;
            for (let i=0;i<300;i++) {
              const ang = Math.random() * Math.PI * 2;
              const rad = Math.sqrt(Math.random()) * maxPx;
              const x = originX + Math.cos(ang) * rad;
              const y = originY + Math.sin(ang) * rad;
              const snapped = targetToken.document.getSnappedPosition({ x: x - targetToken.w / 2, y: y - targetToken.h / 2 });
              const occ = canvas.tokens.placeables.find(t => t.x === snapped.x && t.y === snapped.y);
              if (!occ) { dest = snapped; break; }
            }
            if (dest) {
              console.log("handler: teleport dest found", dest);
              await targetToken.document.parent.moveTokens({ [targetToken.id]: { destination: { x: dest.x, y: dest.y, action: "displace" }, autoRotate: false, showRuler: false } }, { method: "api", animate: false, pan: false }).catch(e => console.warn("handler: teleport token movement failed", e));
              ChatMessage.create({ content: `${targetActor.name} 被传送到距离不超过 30 英尺的空位` });
            } else {
              ChatMessage.create({ content: `${targetActor.name} 未找到空位，跳过传送` });
            }
            const rr = new Roll("10d12"); if (typeof rr.evaluateSync === "function") rr.evaluateSync(); else await rr.roll();
            await new MidiQOL.DamageOnlyWorkflow(casterActor ?? targetActor, casterToken ?? undefined, Number(rr.total), "force", [targetToken], rr, { flavor: "Reality Collapse — 虫洞 (force)" });
            const okProne = await copyItemAEFromOriginToTarget(originUuid, targetActor, ["prone","倒地"]);
            if (!okProne) ChatMessage.create({ content: `${targetActor.name} 未找到倒地 AE（请在施法物品上添加）` });
            else ChatMessage.create({ content: `${targetActor.name} 已被倒地（来自施法物品 AE）` });
            console.groupEnd();
            return;
          }

          // Branch: 9-10 10d12 cold + blind until end of turn
          if (d10 >= 9 && d10 <= 10) {
            console.log("handler: branch 9-10 -> 10d12 cold + blind until end of turn");
            const rr = new Roll("10d12"); if (typeof rr.evaluateSync === "function") rr.evaluateSync(); else await rr.roll();
            await new MidiQOL.DamageOnlyWorkflow(casterActor ?? targetActor, casterToken ?? undefined, Number(rr.total), "cold", [targetToken], rr, { flavor: "Reality Collapse — 暗虚之冻 (cold)" });
            const okBlind = await copyItemAEFromOriginToTarget(originUuid, targetActor, ["blind","盲"]);
            if (!okBlind) ChatMessage.create({ content: `${targetActor.name} 未找到盲目 AE（请在施法物品上添加）` });
            else ChatMessage.create({ content: `${targetActor.name} 被目盲直到本回合结束（来自施法物品 AE）` });
            console.groupEnd();
            return;
          }

          console.groupEnd();
        } catch (err) {
          console.error("RealityCollapse handler unexpected error", err);
        }
      };
      return handler;
    }

    // ==== register (apply) ====
    if (isApply) {
      console.log("RealityCollapse DEBUG: apply branch reached");
      if (!tokenId && !actorId) {
        console.error("RealityCollapse DEBUG: cannot determine tokenId or actorId on apply", lastArg);
        ChatMessage.create({ content: "RealityCollapse: 错误——无法识别目标 tokenId/actorId（查看控制台以获取详细信息）" });
        return;
      }
      // already exists?
      if (window._realityCollapseHooks[efKey]) {
        console.log("RealityCollapse DEBUG: hook already registered for key", efKey, window._realityCollapseHooks[efKey]);
        ChatMessage.create({ content: `RealityCollapse: hook 已存在（key=${efKey}），跳过重复注册` });
        return;
      }
      // try to find a canvas token id fallback (if tokenId is actually a uuid)
      let finalTokenId = tokenId;
      if (String(tokenId)?.startsWith("Scene") || String(tokenId)?.includes(".Token.")) {
        // tokenUuid form — try to resolve
        try {
          const doc = await fromUuid(tokenId).catch(()=>null);
          if (doc && doc.documentName === "Token") finalTokenId = doc.id;
        } catch (e) { console.warn("RealityCollapse DEBUG: tokenId fromUuid failed", e); }
      }
      // ensure token exists on canvas
      let tokenObj = canvas.tokens.get(finalTokenId);
      if (!tokenObj && actorId) {
        tokenObj = canvas.tokens.placeables.find(t => t.actor?.id === actorId);
        if (tokenObj) finalTokenId = tokenObj.id;
      }
      if (!tokenObj) {
        console.warn("RealityCollapse DEBUG: target token not found on canvas during apply", { finalTokenId, actorId });
        ChatMessage.create({ content: `RealityCollapse: 目标 token 在场景上未找到（tokenId=${finalTokenId}, actorId=${actorId}）。请确保目标在场景上。` });
        // still register using finalTokenId (may be undefined) to enable later cleanup attempts
      }

      const originUuid = effect?.origin ?? null;
      const handler = makeHandler(finalTokenId, efKey, originUuid);
      Hooks.on("updateCombat", handler);
      window._realityCollapseHooks[efKey] = {
        handler,
        tokenId: finalTokenId,
        actorId,
        originUuid,
        registeredAt: Date.now(),
        lastArgSnapshot: duplicate(lastArg)
      };
      console.log("RealityCollapse DEBUG: registered hook", efKey, "data:", window._realityCollapseHooks[efKey]);
      ChatMessage.create({ content: `RealityCollapse: hook 已注册 (key=${efKey})，将于目标回合开始时触发表格效果` });
      return;
    }

    // ==== unregister (remove) ====
    if (isRemove) {
      console.log("RealityCollapse DEBUG: remove branch reached for efKey", efKey);
      const rec = window._realityCollapseHooks[efKey];
      if (rec) {
        Hooks.off("updateCombat", rec.handler);
        delete window._realityCollapseHooks[efKey];
        console.log("RealityCollapse DEBUG: unregistered hook for", efKey);
        ChatMessage.create({ content: `RealityCollapse: hook (key=${efKey}) 已注销` });
        return;
      }
      // try alt lookup by tokenId
      const altKey = Object.keys(window._realityCollapseHooks).find(k => window._realityCollapseHooks[k]?.tokenId === tokenId || window._realityCollapseHooks[k]?.actorId === actorId);
      if (altKey) {
        const rec2 = window._realityCollapseHooks[altKey];
        Hooks.off("updateCombat", rec2.handler);
        delete window._realityCollapseHooks[altKey];
        console.log("RealityCollapse DEBUG: unregistered hook (altKey) for", altKey);
        ChatMessage.create({ content: `RealityCollapse: hook (key=${altKey}) 已注销（via alt lookup）` });
        return;
      }
      console.warn("RealityCollapse DEBUG: no registered hook found to remove for", efKey, "tokenId:", tokenId, "actorId:", actorId);
      ChatMessage.create({ content: `RealityCollapse: 未找到已注册 hook (key=${efKey}) 可注销（查看控制台以获取详细信息）` });
      return;
    }

    // If neither apply nor remove detected — print debug and exit
    console.log("RealityCollapse DEBUG: neither apply nor remove detected. lastArg:", lastArg);
    ChatMessage.create({ content: "RealityCollapse: 宏被调用，但未检测到 apply/remove 动作（查看控制台以获取 details）" });
    return;

  } catch (err) {
    console.error("RealityCollapse DEBUG: top-level error", err);
    ChatMessage.create({ content: `RealityCollapse 宏执行出错：${err?.message ?? err}` });
    return;
  }
})();
